(6018017, 881722, 108580, '<td valign="top">Very creative! Can''t vote.</td>', 'Very creative! Can''t vote.', '2010-05-20 06:09:38.000000', NULL, 1),
(6018018, 881781, 108580, '<td valign="top">Lol! Very creative. Can''t vote, wished I could!</td>', 'Lol! Very creative. Can''t vote, wished I could!', '2010-05-20 06:10:22.000000', NULL, 1),
(6018020, 882025, 108580, '<td valign="top">Very clever shot, imaginative.</td>', 'Very clever shot, imaginative.', '2010-05-20 06:15:04.000000', NULL, 1),
(6018024, 881576, 108580, '<td valign="top">That rubber duck is giving you away :)</td>', 'That rubber duck is giving you away :)', '2010-05-20 06:21:00.000000', NULL, 1),
(6018034, 881476, 117741, '<td valign="top">Nice</td>', 'Nice', '2010-05-20 06:53:09.000000', NULL, 1),
(6018096, 882033, 114969, '<td valign="top">A pleasant photography overall, with good light balance. However, I dislike the blurred sides: I am guessing the goal is to put the emphasis on the bag, but instead of that they attracted my eyes to them.</td>', 'A pleasant photography overall, with good light balance. However, I dislike the blurred sides: I am guessing the goal is to put the emphasis on the bag, but instead of that they attracted my eyes to them.', '2010-05-20 09:00:41.000000', NULL, 1),
(6018098, 882227, 114969, '<td valign="top">Nice shot. However, I paid more attention to the girl than the bag ;)</td>', 'Nice shot. However, I paid more attention to the girl than the bag ;)', '2010-05-20 09:02:29.000000', NULL, 1),
(6018104, 882128, 114969, '<td valign="top">There are a bit too much things in the picture in my opinion, it is hard to decide what to look first. In fact, the bag could be easily missed if looked quickly: the composition could probably be improved. Moreover, most of the objects (except the bag) are out of focus, maybe with a smaller aperture?</td>', 'There are a bit too much things in the picture in my opinion, it is hard to decide what to look first. In fact, the bag could be easily missed if looked quickly: the composition could probably be improved. Moreover, most of the objects (except the bag) are out of focus, maybe with a smaller aperture?', '2010-05-20 09:05:32.000000', NULL, 1),
(6018106, 881861, 114969, '<td valign="top">Clever composition... this is creative!</td>', 'Clever composition... this is creative!', '2010-05-20 09:07:12.000000', NULL, 1),
(6018108, 882034, 15711, '<td valign="top">AWWW  CUTE!!!</td>', 'AWWW  CUTE!!!', '2010-05-20 09:14:32.000000', NULL, 1),
